            "Eisa was under an evil spell, or that he really did die back in 2061 and his body has "
            "been a puppet in the hands of an evil spirit ever since -- the shadowland reading is "
            "shedim (Threats 2). Nobody knows where he went. Within a week the Caliph was back in "
            "control of Arabia, President al-Ibrahim of Syria had been killed and replaced by a "
            "national unity government that recalled its troops from the Israeli border, the militant "
            "clerics in Iraq had vanished, and the New Islamic Jihad had scattered worldwide -- with "
